def main() -> None:
    for path, old, new in REPLACEMENTS:
        replace_once(path, old, new)

    (ROOT / 'scanner-api/app/metadata_title_evidence.py').write_text(METADATA_MODULE, encoding='utf-8')
    (ROOT / 'scanner-api/tests/test_metadata_title_evidence_v9.py').write_text(TESTS, encoding='utf-8')
    release_path = ROOT / 'docs/releases/metadata-title-evidence-v9.md'
    release_path.parent.mkdir(parents=True, exist_ok=True)
    release_path.write_text(RELEASE_DOC, encoding='utf-8')

    revision_path = ROOT / 'data/beta-crawler-revision.json'
    revision = json.loads(revision_path.read_text(encoding='utf-8'))
    components = dict(revision.get('component_versions') or {})
    components['metadata_evidence_version'] = 'metadata_evidence_v1_description_states'
    components['title_evidence_version'] = 'title_evidence_v1_contextual_duplicates'
    revision['component_versions'] = dict(sorted(components.items()))
    revision['fingerprint'] = '52348dd1f3b77700'
    revision['git_commit'] = 'dab274d00972218d9d8b54dd76c808edde193256'
    revision['recorded_at'] = '2026-07-18T00:00:00Z'
    revision['note'] = (
        'Metadata/title evidence v9 candidate: absent, empty and malformed meta descriptions are distinct; '
        'duplicate titles are contextualized as localized, query-variant, generic fallback or true template duplicates; '
        'title-width and fallback-title evidence is non-scoring. Funbooker and Sephora focused acceptance required.'
    )
    revision_path.write_text(json.dumps(revision, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')

if __name__ == '__main__':
    main()
